@implementation ContextModelTests

- (void)testNewContextHasUUIDAndIsRoot {
    Context *ctx = [[Context alloc] init];
    XCTAssertNotNil(ctx.uuid);
    XCTAssertGreaterThan(ctx.uuid.length, 0u);
    XCTAssertTrue([ctx isRoot]);
